// Fan out: one item per active platform. Each carries the full property
// context plus that platform's caption-length limit.

const LIMITS = { instagram: 2200, facebook: 63206, linkedin: 3000, tiktok: 2200 };
const src = $input.first().json;
const out = [];

for (const platform of src.platforms) {
  out.push({ json: { ...src, platform, char_limit: LIMITS[platform] ?? 2200 } });
}
return out;

// Postgres node returns { granted: bool } but drops the item context.
// Re-pair it with the platform item by index.
const granted = $input.item.json.granted;
const ctx = $('One Item Per Platform').all()[$itemIndex].json;
return { json: { ...ctx, quota_granted: granted } };

// The model gets ss and CHF formatting wrong intermittently. Fix it in code
// rather than trusting the prompt.

const ctx = $('Quota Granted?').all()[$itemIndex]?.json ?? $input.item.json;
let caption = $input.item.json.choices?.[0]?.message?.content ?? '';

// 1. Swiss spelling: eszett -> ss. The model still emits it sometimes.
caption = caption.replace(/\u00df/g, 'ss');

// 2. Strip stray wrapping quotes the model sometimes adds.
caption = caption.trim().replace(/^["\u201c\u201d']+|["\u201c\u201d']+$/g, '').trim();

// 3. If a price exists, append it in Swiss format: CHF 1'250'000.
//    Apostrophe thousands separator. Never let the model format currency.
if (ctx.price != null && Number(ctx.price) > 0) {
  const chf = 'CHF ' + Math.round(Number(ctx.price)).toLocaleString('de-CH').replace(/\u2019|,/g, "'");
  if (!caption.includes(chf)) caption += '\n\n' + chf;
}

// 4. Enforce the platform hard limit.
const limit = ctx.char_limit ?? 2200;
if (caption.length > limit) caption = caption.slice(0, limit - 1).trimEnd() + '\u2026';

return { json: {
  agent_id: ctx.agent_id,
  property_id: ctx.property_id,
  platform: ctx.platform,
  caption
} };

// Gather created post ids. If at least one exists, hand the property to 03.
const ids = $input.all().map(i => i.json.id).filter(Boolean);
if (ids.length === 0) return [];
const propertyId = $('When Called').first().json.property_id;
return [{ json: { property_id: propertyId, post_count: ids.length } }];
